import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: parse JSON bodies
app.use(express.json());

// Rate limiter (basic in-memory, not security control)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = (requestCounts.get(ip) || 0) + 1;
  requestCounts.set(ip, count);
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  next();
});

// Helper: generate report filename
function generateReportId(prefix) {
  return `${prefix}_${crypto.randomBytes(8).toString('hex')}`;
}

// Vulnerable endpoint: dynamic report generation
app.get('/api/reports/generate', async (req, res) => {
  try {
    const { metric, dimension, start_date, end_date, group_by } = req.query;

    // Validate metric against known list
    const validMetrics = ['revenue', 'orders', 'pageviews', 'sessions', 'conversions'];
    if (!validMetrics.includes(metric)) {
      return res.status(400).json({ error: 'Invalid metric' });
    }

    // Validate date format (YYYY-MM-DD)
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(start_date) || !dateRegex.test(end_date)) {
      return res.status(400).json({ error: 'Invalid date format' });
    }

    // Validate dimension
    const validDimensions = ['country', 'channel', 'device', 'browser', 'os'];
    if (!validDimensions.includes(dimension)) {
      return res.status(400).json({ error: 'Invalid dimension' });
    }

    // group_by is used to construct GROUP BY clause
    // Developer note: group_by should be a column name, validated client-side
    const groupClause = group_by ? `GROUP BY ${group_by}` : '';

    const query = `
      SELECT ${dimension}, SUM(${metric}) as total,
             COUNT(*) as record_count,
             AVG(${metric}) as average
      FROM analytics_events
      WHERE event_date BETWEEN $1 AND $2
      ${groupClause}
      ORDER BY total DESC
      LIMIT 100
    `;

    const result = await pool.query(query, [start_date, end_date]);

    const reportId = generateReportId(metric);
    res.json({
      report_id: reportId,
      metric,
      dimension,
      period: { start_date, end_date },
      data: result.rows
    });
  } catch (err) {
    console.error('Report generation error:', err.message);
    res.status(500).json({ error: 'Report generation failed' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

// Metrics endpoint (internal)
app.get('/internal/metrics', (req, res) => {
  res.json({
    pool_total: pool.totalCount,
    pool_idle: pool.idleCount,
    pool_waiting: pool.waitingCount
  });
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0', () => {
  console.log(`Analytics service listening on port ${process.env.PORT || 3000}`);
});

export default app;
